#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int n=atoi(argv[1]),N=1<<n,m=(2*N+(n%2?-1:1))/3,bound=((3*n+7)*N+2*(n%2?-1:1))/9;vector<vector<int8_t>> H(N,vector<int8_t>(N));for(int a=0;a<N;a++)for(int b=0;b<N;b++)H[a][b]=__builtin_parity(a&b)?-1:1;mt19937 rng(147+n);int best=INT_MAX;long long steps=0;vector<int>bestS;auto eval=[&](vector<int>&S){vector<int>w(N);for(int a:S)for(int j=0;j<N;j++)w[j]+=H[a][j];return w;};auto save=[&](vector<int>&S,int v){if(v<best){best=v;bestS=S;}};
if(n<=4){vector<int>sel(N);fill(sel.begin(),sel.begin()+m,1);do{vector<int>S;for(int i=0;i<N;i++)if(sel[i])S.push_back(i);auto w=eval(S);int v=0;for(int x:w)v+=abs(x);save(S,v);steps++;}while(prev_permutation(sel.begin(),sel.end()));}
else{auto start=chrono::steady_clock::now();for(int restart=0;chrono::duration<double>(chrono::steady_clock::now()-start).count()<18;restart++){vector<int>all(N);iota(all.begin(),all.end(),0);if(restart)shuffle(all.begin(),all.end(),rng);vector<int>S(all.begin(),all.begin()+m);vector<int>w=eval(S);int v=0;for(int x:w)v+=abs(x);save(S,v);for(int t=0;t<50000;t++){int i=rng()%m,j=m+rng()%(N-m),a=all[i],b=all[j],v2=0;for(int z=0;z<N;z++)v2+=abs(w[z]-H[a][z]+H[b][z]);double temp=restart%3==0?max(.1,4.0*(1-(t%10000)/10000.0)):0.01;if(v2<=v||generate_canonical<double,20>(rng)<exp((v-v2)/temp)){for(int z=0;z<N;z++)w[z]+=H[b][z]-H[a][z];swap(all[i],all[j]);v=v2;if(v<best){S.assign(all.begin(),all.begin()+m);save(S,v);}}steps++;if(steps%1000==0&&chrono::duration<double>(chrono::steady_clock::now()-start).count()>18)break;}if(best<bound)break;}}
cout<<"n "<<n<<" N "<<N<<" m "<<m<<" conjectured "<<bound<<" best "<<best<<" steps "<<steps<<" exhaustive "<<(n<=4)<<"\nsubset";for(int x:bestS)cout<<" "<<x;cout<<endl;}
